// Math item generators, K–8. Each skill turns (seeded rng, difficulty, params, story world) into one worksheet item and,
// when asked, the worked-example steps a Support page leads with. Difficulty d = item level shifted by tier:
// Support pages sit one step easier, Stretch one step harder, so the same lesson yields three honest versions.
import type { Tier, Visual, WorkedExample } from './types';
import { type Rng, gcd, lcm, fmtNum, frac } from './rng';
import type { StoryWorld } from './storyIntel';

export interface GenCtx { rng: Rng; level: 1 | 2 | 3; tier: Tier; params: Record<string, number | string>; world: StoryWorld; idx: number }

export interface GenOut {
  prompt: string;
  answer: string | number;
  kind?: 'answer' | 'choice' | 'write' | 'fill';
  choices?: string[];
  visual?: Visual;
  hint?: string;
  numeric?: boolean;
  tolerance?: number;
  lines?: number;
  steps?: string[];
}

export interface MathSkill { label: string; gen: (c: GenCtx) => GenOut }

/** Effective difficulty 1..4. */
export const diff = (c: GenCtx) => Math.max(1, Math.min(4, c.level + (c.tier === 'support' ? -1 : c.tier === 'stretch' ? 1 : 0)));
const by = <T,>(c: GenCtx, opts: [T, T, T, T]) => opts[diff(c) - 1];
const P = (c: GenCtx, k: string, d: number) => (c.params[k] === undefined ? d : Number(c.params[k]));
const N = (c: GenCtx, i = 0) => c.world.names[(c.idx + i) % c.world.names.length];
const T = (c: GenCtx, i = 0) => c.world.things[(c.idx + i) % c.world.things.length];
const pl = (n: number, t: { one: string; many: string }) => `${fmtNum(n)} ${n === 1 ? t.one : t.many}`;

/** Multiple-choice wrapper: correct + distinct distractors, shuffled. */
function mc(c: GenCtx, correct: string | number, wrong: Array<string | number>, n = 4): { choices: string[]; answer: string } {
  const a = String(correct);
  const pool = [...new Set(wrong.map(String).filter(w => w !== a))];
  return { choices: c.rng.shuffle([a, ...c.rng.sample(pool, n - 1)]), answer: a };
}
const near = (c: GenCtx, x: number, spread = 3) => [x + 1, x - 1, x + spread, x - spread, x + 10, x * 2].filter(v => v >= 0 && v !== x);

const SHAPES2D = ['circle', 'square', 'triangle', 'rectangle', 'hexagon', 'pentagon', 'trapezoid', 'rhombus'] as const;
const SHAPES3D = ['cube', 'cylinder', 'cone', 'sphere'] as const;
const SIDES: Record<string, number> = { circle: 0, square: 4, triangle: 3, rectangle: 4, hexagon: 6, pentagon: 5, trapezoid: 4, rhombus: 4 };

function addSub(c: GenCtx, op: '+' | '-', max: number) {
  const lo = max <= 10 ? 0 : max <= 20 ? 1 : max < 200 ? 10 : 100;
  let a = c.rng.int(lo, max), b = c.rng.int(lo, max);
  if (op === '+') { while (a + b > max) { a = c.rng.int(lo, max); b = c.rng.int(lo, Math.max(lo, max - a)); } }
  else if (b > a) [a, b] = [b, a];
  const ans = op === '+' ? a + b : a - b;
  return { a, b, ans };
}

const clockText = (h: number, m: number) => `${h}:${String(m).padStart(2, '0')}`;
const sciN = (x: number) => { const e = Math.floor(Math.log10(Math.abs(x))); const m = +(x / 10 ** e).toFixed(2); return `${m} × 10^${e}`; };

export const MATH_SKILLS: Record<string, MathSkill> = {
  // ── Counting & cardinality ──
  'count.objects': { label: 'Count objects', gen: c => { const n = c.rng.int(by(c, [2, 4, 8, 11]), by(c, [5, 10, 15, 20])); return { prompt: 'How many dots? Count each one and write the number.', answer: n, numeric: true, visual: { type: 'dots', n, cols: 5 }, hint: 'Touch each dot once as you count.', steps: ['Start at the top left.', 'Touch and count each dot once.', `The last number you say is how many: ${n}.`] }; } },
  'count.tenframe': { label: 'Ten frames', gen: c => { const n = c.rng.int(by(c, [1, 3, 6, 11]), by(c, [5, 10, 10, 20])); return { prompt: 'How many are in the ten frame?', answer: n, numeric: true, visual: { type: 'tenframe', n, frames: n > 10 ? 2 : 1 }, hint: 'A full ten frame is 10.', steps: ['A full row holds 5.', 'Count full rows by fives, then count the rest.', `There are ${n}.`] }; } },
  'count.sequence': { label: 'Count on', gen: c => { const step = P(c, 'step', by(c, [1, 1, 2, 5])); const max = P(c, 'max', by(c, [20, 50, 100, 120])); const s = c.rng.int(0, Math.max(0, Math.floor((max - step * 4) / step))) * step; const seq = [s, s + step, s + 2 * step, s + 3 * step]; return { prompt: `What number comes next? ${seq.join(', ')}, ___`, answer: s + 4 * step, numeric: true, hint: `Count on by ${step}.` }; } },
  'count.write': { label: 'Number words', gen: c => { const W = ['zero', 'one', 'two', 'three', 'four', 'five', 'six', 'seven', 'eight', 'nine', 'ten', 'eleven', 'twelve', 'thirteen', 'fourteen', 'fifteen', 'sixteen', 'seventeen', 'eighteen', 'nineteen', 'twenty']; const n = c.rng.int(0, by(c, [5, 10, 15, 20])); return { prompt: `Write the number for the word **${W[n]}**.`, answer: n, numeric: true }; } },
  'compare.numbers': { label: 'Compare numbers', gen: c => { const max = P(c, 'max', by(c, [10, 20, 100, 1000])); const a = c.rng.int(0, max); let b = c.rng.int(0, max); if (c.rng.chance(0.15)) b = a; const sym = a > b ? '>' : a < b ? '<' : '='; return { prompt: `Write >, < or =:   ${fmtNum(a)}  ___  ${fmtNum(b)}`, kind: 'choice', choices: ['<', '>', '='], answer: sym, hint: 'The open mouth eats the bigger number.' }; } },
  'compare.order': { label: 'Order numbers', gen: c => { const max = Math.max(6, P(c, 'max', by(c, [20, 100, 1000, 10000]))); const xs = c.rng.sample(Array.from({ length: max }, (_, i) => i + 1), 4); return { prompt: `Write these numbers from least to greatest: ${xs.map(fmtNum).join(', ')}`, answer: [...xs].sort((a, b) => a - b).map(fmtNum).join(', '), lines: 1 }; } },

  // ── Addition & subtraction ──
  'add.within': { label: 'Add', gen: c => { const max = P(c, 'max', by(c, [10, 20, 100, 1000])); const { a, b, ans } = addSub(c, '+', max); return { prompt: `${fmtNum(a)} + ${fmtNum(b)} = ___`, answer: ans, numeric: true, visual: max <= 10 && c.tier === 'support' ? { type: 'dots', n: a, second: b, cols: 5 } : undefined, hint: max > 20 ? 'Add ones, then tens. Regroup 10 ones as a ten.' : 'Start with the bigger number and count on.', steps: max > 20 ? [`Line up place values: ${a} + ${b}.`, `Add the ones: ${a % 10} + ${b % 10} = ${(a % 10) + (b % 10)}${(a % 10) + (b % 10) >= 10 ? ' — regroup 10 ones as 1 ten' : ''}.`, 'Add the tens (and hundreds), including any regrouped ten.', `Total: ${ans}.`] : [`Start at ${Math.max(a, b)}.`, `Count on ${Math.min(a, b)} more.`, `You land on ${ans}.`] }; } },
  'sub.within': { label: 'Subtract', gen: c => { const max = P(c, 'max', by(c, [10, 20, 100, 1000])); const { a, b, ans } = addSub(c, '-', max); return { prompt: `${fmtNum(a)} − ${fmtNum(b)} = ___`, answer: ans, numeric: true, hint: max > 20 ? 'If there are not enough ones, regroup a ten into 10 ones.' : 'Count back, or think of the addition fact.', steps: max > 20 ? [`Line up place values: ${a} − ${b}.`, (a % 10) < (b % 10) ? `${a % 10} ones is less than ${b % 10} ones, so regroup 1 ten as 10 ones.` : 'Subtract the ones.', 'Subtract the tens (and hundreds).', `Difference: ${ans}. Check: ${ans} + ${b} = ${a}.`] : [`Start at ${a}.`, `Count back ${b}.`, `You land on ${ans}.`] }; } },
  'add.missing': { label: 'Missing addend', gen: c => { const max = P(c, 'max', by(c, [10, 20, 100, 100])); const tot = c.rng.int(Math.min(5, max), max); const a = c.rng.int(0, tot); return { prompt: `${a} + ___ = ${tot}`, answer: tot - a, numeric: true, hint: `Count up from ${a} to ${tot}.` }; } },
  'make10': { label: 'Make ten', gen: c => { const t = P(c, 'target', 10); const a = c.rng.int(1, t - 1); return { prompt: `${a} + ___ = ${t}`, answer: t - a, numeric: true, visual: t === 10 ? { type: 'tenframe', n: a } : undefined, hint: 'Count the empty boxes.' }; } },
  'teen.decompose': { label: 'Teen numbers', gen: c => { const n = c.rng.int(11, 19); return c.rng.chance(0.5) ? { prompt: `${n} = 10 + ___`, answer: n - 10, numeric: true, visual: { type: 'tenframe', n, frames: 2 } } : { prompt: `10 + ${n - 10} = ___`, answer: n, numeric: true }; } },
  'add.word': { label: 'Addition stories', gen: c => { const max = P(c, 'max', by(c, [10, 20, 100, 1000])); const { a, b, ans } = addSub(c, '+', max); const t = T(c); return { prompt: `${N(c)} has ${pl(a, t)} at ${c.world.place}. ${N(c, 1)} brings ${fmtNum(b)} more ${b === 1 ? t.one : t.many}. How many ${t.many} are there now?`, answer: ans, numeric: true, lines: 1, hint: 'Joining groups means add.', steps: ['Find the two groups.', `${a} + ${b}`, `${ans} ${t.many}.`] }; } },
  'sub.word': { label: 'Subtraction stories', gen: c => { const max = P(c, 'max', by(c, [10, 20, 100, 1000])); const { a, b, ans } = addSub(c, '-', max); const t = T(c); return { prompt: `There were ${pl(a, t)} at ${c.world.place}. ${N(c)} gave away ${fmtNum(b)}. How many ${t.many} are left?`, answer: ans, numeric: true, lines: 1, hint: 'Taking away means subtract.', steps: ['Start with the whole.', `${a} − ${b}`, `${ans} ${t.many} left.`] }; } },
  'compare.word': { label: 'How many more', gen: c => { const max = P(c, 'max', by(c, [10, 20, 100, 1000])); const a = c.rng.int(Math.ceil(max / 3), max); const b = c.rng.int(0, a - 1); const t = T(c); return { prompt: `${N(c)} has ${pl(a, t)}. ${N(c, 1)} has ${pl(b, t)}. How many more ${t.many} does ${N(c)} have?`, answer: a - b, numeric: true, lines: 1, visual: max <= 50 ? { type: 'barModel', parts: [{ label: String(b), size: b }, { label: '?', size: a - b }], total: String(a) } : undefined }; } },
  'twostep.word': { label: 'Two-step problems', gen: c => { const big = diff(c) >= 3; const a = c.rng.int(big ? 20 : 5, big ? 300 : 40), b = c.rng.int(2, big ? 90 : 15), d = c.rng.int(1, Math.max(1, a + b - 1)); const t = T(c); return { prompt: `${N(c)} had ${pl(a, t)}. Then ${N(c)} got ${fmtNum(b)} more and used ${fmtNum(d)} for ${c.world.activity}. How many ${t.many} are left?`, answer: a + b - d, numeric: true, lines: 2, hint: 'Do one step at a time: add, then subtract.', steps: [`Step 1: ${a} + ${b} = ${a + b}.`, `Step 2: ${a + b} − ${d} = ${a + b - d}.`] }; } },
  'add.tens': { label: 'Add tens', gen: c => { const a = c.rng.int(1, 8) * 10, b = c.rng.int(1, Math.max(1, 9 - a / 10)) * 10; return { prompt: `${a} + ${b} = ___`, answer: a + b, numeric: true, hint: `${a / 10} tens + ${b / 10} tens.` }; } },
  'tens.more': { label: '10 more, 10 less', gen: c => { const n = c.rng.int(by(c, [10, 10, 100, 100]), by(c, [89, 89, 889, 9989])); const unit = diff(c) >= 3 ? 100 : 10; const more = c.rng.chance(0.5); return { prompt: `${unit} ${more ? 'more' : 'less'} than ${fmtNum(n)} is ___`, answer: more ? n + unit : n - unit, numeric: true }; } },
  'numberline.add': { label: 'Number line jumps', gen: c => { const a = c.rng.int(0, 10), b = c.rng.int(1, 10); return { prompt: `Use the number line. Start at ${a} and jump ${b}. Where do you land?`, answer: a + b, numeric: true, visual: { type: 'numberline', min: 0, max: 20, step: 1, marks: [a], labels: 'all' } }; } },
  'evenodd': { label: 'Even and odd', gen: c => { const n = c.rng.int(1, by(c, [20, 20, 100, 1000])); return { prompt: `Is ${n} even or odd?`, kind: 'choice', choices: ['even', 'odd'], answer: n % 2 ? 'odd' : 'even', hint: 'Even numbers can be split into two equal groups.' }; } },
  'skipcount': { label: 'Skip count', gen: c => { const step = P(c, 'step', c.rng.pick([2, 5, 10, 100])); const s = c.rng.int(0, 10) * step; return { prompt: `Skip count by ${step}s: ${s}, ${s + step}, ${s + 2 * step}, ___, ___`, answer: `${s + 3 * step}, ${s + 4 * step}`, lines: 1 }; } },

  // ── Place value ──
  'placevalue.base10': { label: 'Base-ten blocks', gen: c => { const h = diff(c) >= 3 ? c.rng.int(1, 9) : 0, t = c.rng.int(1, 9), o = c.rng.int(0, 9); return { prompt: 'What number do the blocks show?', answer: h * 100 + t * 10 + o, numeric: true, visual: { type: 'base10', hundreds: h, tens: t, ones: o }, hint: 'Rods are tens, small cubes are ones, flats are hundreds.' }; } },
  'placevalue.digit': { label: 'Value of a digit', gen: c => { const digits = by(c, [2, 3, 4, 6]); const n = c.rng.int(10 ** (digits - 1), 10 ** digits - 1); const s = String(n); const i = c.rng.int(0, s.length - 1); const names = ['ones', 'tens', 'hundreds', 'thousands', 'ten thousands', 'hundred thousands']; const place = s.length - 1 - i; return { prompt: `In ${fmtNum(n)}, what is the value of the digit ${s[i]}?`, answer: Number(s[i]) * 10 ** place, numeric: true, hint: `The ${s[i]} is in the ${names[place]} place.` }; } },
  'placevalue.expanded': { label: 'Expanded form', gen: c => { const digits = by(c, [2, 3, 4, 5]); const n = c.rng.int(10 ** (digits - 1), 10 ** digits - 1); const parts = String(n).split('').map((d, i, a) => Number(d) * 10 ** (a.length - 1 - i)).filter(Boolean); return { prompt: `Write ${fmtNum(n)} in expanded form.`, answer: parts.map(fmtNum).join(' + '), lines: 1 }; } },
  'round': { label: 'Rounding', gen: c => { const to = P(c, 'to', by(c, [10, 10, 100, 1000])); const n = c.rng.int(to + 1, to * 99); return { prompt: `Round ${fmtNum(n)} to the nearest ${fmtNum(to)}.`, answer: fmtNum(Math.round(n / to) * to), numeric: true, hint: 'Look at the digit to the right. 5 or more rounds up.' }; } },

  // ── Multiplication & division ──
  'array.total': { label: 'Arrays', gen: c => { const r = c.rng.int(2, by(c, [3, 5, 6, 9])), k = c.rng.int(2, by(c, [4, 5, 8, 10])); return { prompt: `Write a repeated addition and a multiplication for the array. How many in all?`, answer: r * k, numeric: true, visual: { type: 'array', rows: r, cols: k }, steps: [`${r} rows of ${k}.`, `${Array(r).fill(k).join(' + ')} = ${r * k}.`, `${r} × ${k} = ${r * k}.`] }; } },
  'mult.facts': { label: 'Multiplication facts', gen: c => { const max = P(c, 'max', by(c, [5, 10, 10, 12])); const a = c.rng.int(by(c, [1, 2, 3, 6]), max), b = c.rng.int(by(c, [1, 2, 3, 4]), max); return { prompt: `${a} × ${b} = ___`, answer: a * b, numeric: true, hint: `Think ${b} groups of ${a}.`, steps: [`${a} × ${b} means ${b} groups of ${a}.`, `Use a fact you know: ${a} × ${Math.max(1, b - 1)} = ${a * Math.max(1, b - 1)}.`, b > 1 ? `Add one more group of ${a}: ${a * (b - 1)} + ${a} = ${a * b}.` : `${a * b}.`] }; } },
  'div.facts': { label: 'Division facts', gen: c => { const max = P(c, 'max', by(c, [5, 10, 10, 12])); const b = c.rng.int(2, max), q = c.rng.int(1, max); return { prompt: `${b * q} ÷ ${b} = ___`, answer: q, numeric: true, hint: `Think: ${b} × ? = ${b * q}.`, steps: [`Division undoes multiplication.`, `Ask: ${b} times what makes ${b * q}?`, `${b} × ${q} = ${b * q}, so ${b * q} ÷ ${b} = ${q}.`] }; } },
  'mult.missing': { label: 'Unknown factor', gen: c => { const a = c.rng.int(2, 10), b = c.rng.int(2, 10); return { prompt: `${a} × ___ = ${a * b}`, answer: b, numeric: true }; } },
  'mult.word': { label: 'Equal groups stories', gen: c => { const g = c.rng.int(2, by(c, [5, 9, 12, 25])), e = c.rng.int(2, by(c, [5, 9, 12, 15])); const t = T(c), k = c.world.container; return { prompt: `${N(c)} has ${pl(g, k)}. Each ${k.one} holds ${pl(e, t)}. How many ${t.many} in all?`, answer: g * e, numeric: true, lines: 1, visual: g * e <= 40 && c.tier === 'support' ? { type: 'array', rows: g, cols: e } : undefined, steps: ['Equal groups → multiply.', `${g} × ${e} = ${g * e}.`] }; } },
  'div.word': { label: 'Sharing stories', gen: c => { const g = c.rng.int(2, by(c, [5, 9, 12, 25])), e = c.rng.int(2, by(c, [5, 9, 12, 15])); const t = T(c); return { prompt: `${N(c)} shares ${pl(g * e, t)} equally among ${g} friends at ${c.world.place}. How many ${t.many} does each friend get?`, answer: e, numeric: true, lines: 1, steps: ['Sharing equally → divide.', `${g * e} ÷ ${g} = ${e}.`] }; } },
  'mult.distributive': { label: 'Break apart to multiply', gen: c => { const a = c.rng.int(3, 9), b = c.rng.int(6, 12), s = c.rng.int(2, b - 2); return { prompt: `${a} × ${b} = ${a} × ${s} + ${a} × ___`, answer: b - s, numeric: true, hint: `${s} + ? = ${b}` }; } },
  'mult.multidigit': { label: 'Multi-digit multiplication', gen: c => { const [ad, bd] = ([[2, 1], [3, 1], [2, 2], [4, 2]] as const)[diff(c) - 1]; const a = c.rng.int(10 ** (ad - 1), 10 ** ad - 1), b = c.rng.int(Math.max(2, 10 ** (bd - 1)), 10 ** bd - 1); return { prompt: `${fmtNum(a)} × ${fmtNum(b)} = ___`, answer: a * b, numeric: true, lines: 3, hint: 'Use partial products or the area model.', steps: bd === 1 ? [`Break ${a} into place values.`, ...String(a).split('').map((d, i, arr) => `${Number(d) * 10 ** (arr.length - 1 - i)} × ${b} = ${Number(d) * 10 ** (arr.length - 1 - i) * b}`), `Add the partial products: ${a * b}.`] : [`${a} × ${b % 10} = ${a * (b % 10)}`, `${a} × ${b - (b % 10)} = ${a * (b - (b % 10))}`, `Add: ${a * b}.`] }; } },
  'div.long': { label: 'Long division', gen: c => { const dv = c.rng.int(2, by(c, [5, 9, 9, 25])); const q = c.rng.int(by(c, [11, 12, 101, 101]), by(c, [30, 99, 999, 999])); const r = diff(c) >= 2 ? c.rng.int(0, dv - 1) : 0; return { prompt: `${fmtNum(dv * q + r)} ÷ ${dv} = ___`, answer: r ? `${q} R${r}` : q, numeric: !r, lines: 3, hint: 'Divide, multiply, subtract, bring down.', steps: [`How many ${dv}s fit in the first digits?`, 'Multiply and subtract; bring down the next digit.', 'Repeat until every digit is used.', `${dv * q + r} ÷ ${dv} = ${q}${r ? ` R${r}` : ''}.`] }; } },
  'factors': { label: 'Factors', gen: c => { const n = c.rng.pick(by(c, [[6, 8, 10, 12], [12, 16, 18, 20, 24], [24, 30, 36, 40, 48], [48, 60, 72, 84, 96]])); const fs = Array.from({ length: n }, (_, i) => i + 1).filter(d => n % d === 0); return { prompt: `List all the factors of ${n}.`, answer: fs.join(', '), lines: 1, hint: 'Find factor pairs: 1 × ?, 2 × ?, …' }; } },
  'multiples': { label: 'Multiples', gen: c => { const n = c.rng.int(2, 12); return { prompt: `Write the first five multiples of ${n}.`, answer: [1, 2, 3, 4, 5].map(k => k * n).join(', '), lines: 1 }; } },
  'prime': { label: 'Prime or composite', gen: c => { const n = c.rng.int(2, by(c, [20, 50, 100, 100])); const isP = n > 1 && Array.from({ length: n - 2 }, (_, i) => i + 2).every(d => n % d); return { prompt: `Is ${n} prime or composite?`, kind: 'choice', choices: ['prime', 'composite'], answer: isP ? 'prime' : 'composite', hint: 'A prime number has exactly two factors.' }; } },
  'pattern.rule': { label: 'Patterns and rules', gen: c => { const s = c.rng.int(1, 20), k = c.rng.int(2, by(c, [3, 5, 9, 12])); const mult = diff(c) >= 3 && c.rng.chance(0.5); const seq = mult ? [s, s * k, s * k * k].slice(0, 3) : [s, s + k, s + 2 * k, s + 3 * k]; return { prompt: `Find the rule and the next number: ${seq.join(', ')}, ___`, answer: mult ? seq[seq.length - 1] * k : s + 4 * k, numeric: true, hint: mult ? 'Is it multiplying?' : 'How much is added each time?' }; } },

  // ── Fractions ──
  'fraction.identify': { label: 'Name the fraction', gen: c => { const d = P(c, 'den', c.rng.pick(by(c, [[2, 4], [2, 3, 4], [2, 3, 4, 6, 8], [3, 5, 6, 8, 10, 12]]))); const n = c.rng.int(1, d - (d > 2 ? 0 : 1)); return { prompt: 'What fraction is shaded?', answer: `${n}/${d}`, visual: { type: 'fraction', parts: d, shaded: n, shape: c.rng.chance(0.5) ? 'bar' : 'circle' }, hint: 'Shaded parts over total equal parts.' }; } },
  'fraction.numberline': { label: 'Fractions on a number line', gen: c => { const d = c.rng.pick([2, 3, 4, 6, 8]); const n = c.rng.int(1, d - 1); return { prompt: 'What fraction does the dot show?', answer: `${n}/${d}`, visual: { type: 'numberline', min: 0, max: 1, step: 1 / d, marks: [n / d], labels: 'ends', fractionDen: d }, hint: `The space from 0 to 1 is cut into ${d} equal parts.` }; } },
  'fraction.equivalent': { label: 'Equivalent fractions', gen: c => { const d = c.rng.pick([2, 3, 4, 5, 6]); const n = c.rng.int(1, d - 1); const k = c.rng.int(2, by(c, [2, 4, 5, 8])); return { prompt: `${n}/${d} = ___/${d * k}`, answer: n * k, numeric: true, visual: c.tier === 'support' ? { type: 'fraction', parts: d, shaded: n, shape: 'bar' } : undefined, hint: `Multiply the top and bottom by the same number (${k}).`, steps: [`The denominator went from ${d} to ${d * k}: ×${k}.`, `Do the same to the numerator: ${n} × ${k} = ${n * k}.`, `${n}/${d} = ${n * k}/${d * k}.`] }; } },
  'fraction.compare': { label: 'Compare fractions', gen: c => { const sameDen = diff(c) <= 2; const d1 = c.rng.pick([3, 4, 5, 6, 8]); const d2 = sameDen ? d1 : c.rng.pick([2, 3, 4, 6, 8, 10, 12]); const n1 = c.rng.int(1, d1 - 1), n2 = c.rng.int(1, d2 - 1); const v = n1 / d1 - n2 / d2; return { prompt: `Compare: ${n1}/${d1} ___ ${n2}/${d2}`, kind: 'choice', choices: ['<', '>', '='], answer: Math.abs(v) < 1e-9 ? '=' : v > 0 ? '>' : '<', hint: sameDen ? 'Same size parts: compare the numerators.' : 'Make common denominators, or compare to 1/2.' }; } },
  'fraction.add.like': { label: 'Add/subtract like denominators', gen: c => { const d = c.rng.pick([4, 5, 6, 8, 10, 12]); const a = c.rng.int(1, d - 1), b = c.rng.int(1, d - 1); const sub = c.rng.chance(0.4); const [x, y] = sub && b > a ? [b, a] : [a, b]; return { prompt: `${x}/${d} ${sub ? '−' : '+'} ${y}/${d} = ___`, answer: `${sub ? x - y : x + y}/${d}`, hint: 'Keep the denominator; add or subtract the numerators.' }; } },
  'fraction.mixed': { label: 'Mixed numbers', gen: c => { const d = c.rng.pick([2, 3, 4, 5, 6, 8]); const w = c.rng.int(1, 5), n = c.rng.int(1, d - 1); return c.rng.chance(0.5) ? { prompt: `Write ${w} ${n}/${d} as an improper fraction.`, answer: `${w * d + n}/${d}` } : { prompt: `Write ${w * d + n}/${d} as a mixed number.`, answer: `${w} ${n}/${d}` }; } },
  'fraction.times.whole': { label: 'Fraction × whole number', gen: c => { const d = c.rng.pick([2, 3, 4, 5, 6, 8]); const n = c.rng.int(1, d - 1), w = c.rng.int(2, 9); return { prompt: `${w} × ${n}/${d} = ___`, answer: frac(w * n, d), hint: `${w} groups of ${n}/${d}.` }; } },
  'fraction.add.unlike': { label: 'Add/subtract unlike denominators', gen: c => { const d1 = c.rng.pick([2, 3, 4, 5, 6]), d2 = c.rng.pick([3, 4, 6, 8, 10, 12].filter(x => x !== d1)); const n1 = c.rng.int(1, d1 - 1), n2 = c.rng.int(1, d2 - 1); const L = lcm(d1, d2); const sub = c.rng.chance(0.4) && n1 / d1 > n2 / d2; const num = sub ? n1 * (L / d1) - n2 * (L / d2) : n1 * (L / d1) + n2 * (L / d2); return { prompt: `${n1}/${d1} ${sub ? '−' : '+'} ${n2}/${d2} = ___`, answer: frac(num, L), lines: 2, hint: `Common denominator: ${L}.`, steps: [`Find a common denominator: ${L}.`, `${n1}/${d1} = ${n1 * (L / d1)}/${L} and ${n2}/${d2} = ${n2 * (L / d2)}/${L}.`, `${sub ? 'Subtract' : 'Add'} numerators: ${num}/${L}.`, `Simplify: ${frac(num, L)}.`] }; } },
  'fraction.mult': { label: 'Multiply fractions', gen: c => { const d1 = c.rng.int(2, 9), d2 = c.rng.int(2, 9), n1 = c.rng.int(1, d1 - 1), n2 = c.rng.int(1, d2 - 1); return { prompt: `${n1}/${d1} × ${n2}/${d2} = ___`, answer: frac(n1 * n2, d1 * d2), hint: 'Multiply tops, multiply bottoms, then simplify.' }; } },
  'fraction.div': { label: 'Divide fractions', gen: c => { const unit = diff(c) <= 2; if (unit) { const w = c.rng.int(2, 9), d = c.rng.int(2, 6); return c.rng.chance(0.5) ? { prompt: `${w} ÷ 1/${d} = ___`, answer: w * d, numeric: true, hint: `How many 1/${d}s fit in ${w}?` } : { prompt: `1/${d} ÷ ${w} = ___`, answer: `1/${d * w}` }; } const d1 = c.rng.int(2, 9), d2 = c.rng.int(2, 9), n1 = c.rng.int(1, d1 - 1), n2 = c.rng.int(1, d2 - 1); return { prompt: `${n1}/${d1} ÷ ${n2}/${d2} = ___`, answer: frac(n1 * d2, d1 * n2), hint: 'Multiply by the reciprocal.', steps: [`Keep ${n1}/${d1}, change ÷ to ×, flip ${n2}/${d2} to ${d2}/${n2}.`, `${n1}/${d1} × ${d2}/${n2} = ${n1 * d2}/${d1 * n2}.`, `Simplify: ${frac(n1 * d2, d1 * n2)}.`] }; } },

  // ── Decimals ──
  'decimal.fraction': { label: 'Decimals and fractions', gen: c => { const hund = diff(c) >= 2; const n = hund ? c.rng.int(1, 99) : c.rng.int(1, 9); const d = hund ? 100 : 10; return c.rng.chance(0.5) ? { prompt: `Write ${n}/${d} as a decimal.`, answer: (n / d).toFixed(hund ? 2 : 1), numeric: true } : { prompt: `Write ${(n / d).toFixed(hund ? 2 : 1)} as a fraction with denominator ${d}.`, answer: `${n}/${d}` }; } },
  'decimal.compare': { label: 'Compare decimals', gen: c => { const a = c.rng.int(1, 999) / 100, b = c.rng.chance(0.5) ? Math.round(a * 10) / 10 : c.rng.int(1, 999) / 100; return { prompt: `Compare: ${a} ___ ${b}`, kind: 'choice', choices: ['<', '>', '='], answer: a > b ? '>' : a < b ? '<' : '=', hint: 'Line up the decimal points; compare place by place.' }; } },
  'decimal.addsub': { label: 'Add/subtract decimals', gen: c => { const p = by(c, [1, 2, 2, 3]); const a = c.rng.int(10, 9999) / 10 ** p, b = c.rng.int(10, 999) / 10 ** p; const sub = c.rng.chance(0.5); const [x, y] = sub && b > a ? [b, a] : [a, b]; return { prompt: `${x} ${sub ? '−' : '+'} ${y} = ___`, answer: +(sub ? x - y : x + y).toFixed(p), numeric: true, tolerance: 1e-6, hint: 'Line up the decimal points.' }; } },
  'decimal.mult': { label: 'Multiply decimals', gen: c => { const a = c.rng.int(2, 99) / 10, b = diff(c) >= 3 ? c.rng.int(2, 99) / 10 : c.rng.int(2, 9); return { prompt: `${a} × ${b} = ___`, answer: +(a * b).toFixed(2), numeric: true, tolerance: 1e-6, hint: 'Multiply as whole numbers, then count decimal places.' }; } },
  'decimal.div': { label: 'Divide decimals', gen: c => { const b = diff(c) >= 3 ? c.rng.int(2, 9) / 10 : c.rng.int(2, 9); const q = c.rng.int(2, 99) / 10; return { prompt: `${+(b * q).toFixed(2)} ÷ ${b} = ___`, answer: q, numeric: true, tolerance: 1e-6, hint: b < 1 ? 'Move both decimal points so the divisor is a whole number.' : 'Divide; keep the decimal point above.' }; } },
  'powers.ten': { label: 'Powers of ten', gen: c => { const x = c.rng.int(1, 999) / 10; const e = c.rng.int(1, 3); const m = c.rng.chance(0.5); return { prompt: `${x} ${m ? '×' : '÷'} ${10 ** e} = ___`, answer: +(m ? x * 10 ** e : x / 10 ** e).toFixed(5), numeric: true, tolerance: 1e-6, hint: `Move the decimal point ${e} place${e > 1 ? 's' : ''} ${m ? 'right' : 'left'}.` }; } },

  // ── Measurement & data ──
  'time.clock': { label: 'Tell time', gen: c => { const step = P(c, 'step', by(c, [30, 30, 5, 1])); const h = c.rng.int(1, 12), m = c.rng.int(0, Math.floor(59 / step)) * step; return { prompt: 'What time does the clock show?', answer: clockText(h, m), visual: { type: 'clock', h, m }, hint: 'Short hand: hour. Long hand: minutes.' }; } },
  'time.elapsed': { label: 'Elapsed time', gen: c => { const h = c.rng.int(7, 15), m = c.rng.int(0, 11) * 5, dur = c.rng.int(2, by(c, [6, 12, 20, 36])) * 5; const end = h * 60 + m + dur; const fmt = (t: number) => clockText(((Math.floor(t / 60) + 11) % 12) + 1, t % 60); return { prompt: `${N(c)} starts ${c.world.activity} at ${fmt(h * 60 + m)} and finishes at ${fmt(end)}. How many minutes is that?`, answer: dur, numeric: true, lines: 1, hint: 'Count up to the next hour, then the rest.' }; } },
  'money.coins': { label: 'Count coins', gen: c => { const kinds = ['quarter', 'dime', 'nickel', 'penny'] as const; const coins = Array.from({ length: c.rng.int(2, by(c, [3, 5, 6, 8])) }, () => c.rng.pick(kinds)).sort((a, b) => kinds.indexOf(a) - kinds.indexOf(b)); const val = { quarter: 25, dime: 10, nickel: 5, penny: 1 }; return { prompt: 'How many cents?', answer: `${coins.reduce((s, k) => s + val[k], 0)}¢`, visual: { type: 'coins', coins }, hint: 'Start with the coin worth the most.' }; } },
  'measure.units': { label: 'Choose the unit', gen: c => { const items: Array<[string, string, string[]]> = [['the length of a pencil', 'centimeters', ['meters', 'kilometers', 'liters']], ['the height of a door', 'meters', ['centimeters', 'kilometers', 'grams']], ['the distance between two cities', 'kilometers', ['centimeters', 'meters', 'kilograms']], ['the mass of an apple', 'grams', ['kilograms', 'liters', 'meters']], ['water in a bathtub', 'liters', ['milliliters', 'grams', 'meters']], ['the mass of a dog', 'kilograms', ['grams', 'liters', 'centimeters']]]; const [what, ans, wrong] = c.rng.pick(items); return { prompt: `Which unit is best to measure ${what}?`, kind: 'choice', ...mc(c, ans, wrong) }; } },
  'measure.convert': { label: 'Convert units', gen: c => { const conv: Array<[string, string, number]> = by(c, [[['feet', 'inches', 12], ['yards', 'feet', 3], ['hours', 'minutes', 60]], [['meters', 'centimeters', 100], ['kilograms', 'grams', 1000], ['minutes', 'seconds', 60]], [['kilometers', 'meters', 1000], ['liters', 'milliliters', 1000], ['pounds', 'ounces', 16]], [['gallons', 'quarts', 4], ['kilometers', 'meters', 1000], ['days', 'hours', 24]]]); const [big, small, f] = c.rng.pick(conv); const n = c.rng.int(2, 12); return { prompt: `${n} ${big} = ___ ${small}`, answer: n * f, numeric: true, hint: `1 ${big.replace(/s$/, '')} = ${f} ${small}.` }; } },
  'measure.compare': { label: 'Compare lengths', gen: c => { const objs = ['pencil', 'crayon', 'ribbon', 'stick', 'paper strip', 'shoelace', 'leaf', 'spoon']; const [o1, o2] = c.rng.sample(objs, 2); const a = c.rng.int(3, 30); let b = c.rng.int(3, 30); if (b === a) b += 2; return { prompt: `A ${o1} is ${a} cm long. A ${o2} is ${b} cm long. Which is longer?`, kind: 'choice', choices: [o1, o2], answer: a > b ? o1 : o2 }; } },
  'data.tally': { label: 'Tally marks', gen: c => { const n = c.rng.int(3, by(c, [10, 15, 20, 25])); return { prompt: 'How many do the tally marks show?', answer: n, numeric: true, visual: { type: 'tally', n }, hint: 'Each bundle is 5.' }; } },
  'data.bar': { label: 'Read a bar graph', gen: c => { const scale = by(c, [1, 2, 5, 10]); const labels = c.world.things.slice(0, 3).map(t => t.many); const values = labels.map(() => c.rng.int(1, 8) * scale); const i = c.rng.int(0, 2), j = (i + 1) % 3; const ask = c.rng.chance(0.5); return { prompt: ask ? `How many ${labels[i]} are there?` : `How many more ${labels[i]} than ${labels[j]}? (Write a negative number if fewer.)`, answer: ask ? values[i] : values[i] - values[j], numeric: true, visual: { type: 'barChart', labels, values, scale } }; } },
  'area.grid': { label: 'Area by counting', gen: c => { const w = c.rng.int(2, by(c, [4, 6, 8, 10])), h = c.rng.int(2, by(c, [3, 5, 6, 8])); return { prompt: 'What is the area of the rectangle in square units?', answer: w * h, numeric: true, visual: { type: 'gridRect', w, h, showGrid: true }, hint: 'Count the squares, or multiply rows × columns.' }; } },
  'area.rect': { label: 'Area and perimeter', gen: c => { const w = c.rng.int(2, by(c, [8, 12, 20, 40])), h = c.rng.int(2, by(c, [6, 10, 15, 30])); const perim = c.rng.chance(0.5); return { prompt: `A rectangle is ${w} m long and ${h} m wide. Find its ${perim ? 'perimeter' : 'area'}.`, answer: perim ? 2 * (w + h) : w * h, numeric: true, lines: 1, visual: { type: 'gridRect', w: Math.min(w, 12), h: Math.min(h, 8), showGrid: false, label: true }, hint: perim ? 'Add all four sides.' : 'Length × width.', steps: perim ? [`Perimeter = ${w} + ${h} + ${w} + ${h}`, `= ${2 * (w + h)} m.`] : [`Area = length × width`, `= ${w} × ${h} = ${w * h} square meters.`] }; } },
  'area.polygon': { label: 'Area of triangles and parallelograms', gen: c => { const b = c.rng.int(3, 20), h = c.rng.int(2, 15); const kind = c.rng.pick(['triangle', 'parallelogram', 'trapezoid'] as const); if (kind === 'trapezoid') { const b2 = c.rng.int(2, 18); return { prompt: `A trapezoid has bases ${b} cm and ${b2} cm and height ${h} cm. Find its area.`, answer: ((b + b2) * h) / 2, numeric: true, lines: 1, hint: 'A = ½(b₁ + b₂)h' }; } return { prompt: `A ${kind} has base ${b} cm and height ${h} cm. Find its area.`, answer: kind === 'triangle' ? (b * h) / 2 : b * h, numeric: true, lines: 1, hint: kind === 'triangle' ? 'A = ½ × b × h' : 'A = b × h', visual: { type: 'shape', shape: kind === 'triangle' ? 'triangle' : 'rhombus' } }; } },
  'volume.prism': { label: 'Volume of prisms', gen: c => { const l = c.rng.int(2, by(c, [4, 6, 10, 15])), w = c.rng.int(2, by(c, [3, 5, 8, 12])), h = c.rng.int(2, by(c, [3, 5, 8, 10])); return { prompt: `Find the volume of the box: ${l} × ${w} × ${h} units.`, answer: l * w * h, numeric: true, visual: { type: 'prism', l, w, h }, hint: 'V = length × width × height.' }; } },
  'angle.classify': { label: 'Classify angles', gen: c => { const d = c.rng.pick([30, 45, 60, 90, 120, 135, 150, 180]); return { prompt: 'Is this angle acute, right, obtuse or straight?', kind: 'choice', choices: ['acute', 'right', 'obtuse', 'straight'], answer: d < 90 ? 'acute' : d === 90 ? 'right' : d < 180 ? 'obtuse' : 'straight', visual: { type: 'angle', degrees: d } }; } },
  'angle.missing': { label: 'Angle relationships', gen: c => { const kind = c.rng.pick(['complementary', 'supplementary', 'triangle'] as const); if (kind === 'triangle') { const a = c.rng.int(20, 90), b = c.rng.int(20, 160 - a); return { prompt: `Two angles of a triangle are ${a}° and ${b}°. Find the third angle.`, answer: 180 - a - b, numeric: true, hint: 'Triangle angles sum to 180°.' }; } const tot = kind === 'complementary' ? 90 : 180; const a = c.rng.int(10, tot - 10); return { prompt: `Two ${kind} angles: one is ${a}°. What is the other?`, answer: tot - a, numeric: true, hint: `${kind} angles add to ${tot}°.` }; } },
  'shapes.identify': { label: 'Name the shape', gen: c => { const s = c.rng.pick(SHAPES2D); return { prompt: 'What is the name of this shape?', kind: 'choice', visual: { type: 'shape', shape: s }, ...mc(c, s, SHAPES2D.filter(x => x !== s), by(c, [3, 3, 4, 4])) }; } },
  'shapes.attributes': { label: 'Shape attributes', gen: c => { const s = c.rng.pick(SHAPES2D.filter(x => x !== 'circle')); return { prompt: `How many sides does a ${s} have?`, answer: SIDES[s], numeric: true, visual: { type: 'shape', shape: s } }; } },
  'shapes.3d': { label: '3-D shapes', gen: c => { const s = c.rng.pick(SHAPES3D); return { prompt: 'What is the name of this solid shape?', kind: 'choice', visual: { type: 'shape', shape: s }, ...mc(c, s, SHAPES3D.filter(x => x !== s), 3) }; } },
  'coord.plot': { label: 'Coordinate plane', gen: c => { const size = by(c, [5, 8, 10, 10]); const x = c.rng.int(0, size), y = c.rng.int(0, size); return { prompt: 'Write the coordinates of point A as (x, y).', answer: `(${x}, ${y})`, visual: { type: 'coord', points: [[x, y, 'A']], size }, hint: 'Go across first (x), then up (y).' }; } },
  'coord.quadrants': { label: 'Four quadrants', gen: c => { const x = c.rng.int(-6, 6) || 2, y = c.rng.int(-6, 6) || -3; const q = x > 0 && y > 0 ? 'I' : x < 0 && y > 0 ? 'II' : x < 0 ? 'III' : 'IV'; return { prompt: `In which quadrant is the point (${x}, ${y})?`, kind: 'choice', choices: ['I', 'II', 'III', 'IV'], answer: q }; } },
  'order.ops': { label: 'Order of operations', gen: c => { const a = c.rng.int(2, 12), b = c.rng.int(2, 9), d = c.rng.int(2, 9), e = c.rng.int(1, 20); const forms: Array<[string, number]> = [[`${a} + ${b} × ${d}`, a + b * d], [`(${a} + ${b}) × ${d}`, (a + b) * d], [`${e + b * d} − ${b} × ${d} + ${a}`, e + a], [`${a * d} ÷ ${d} + ${b}²`, a + b * b]]; const [ex, v] = forms[Math.min(forms.length - 1, diff(c) - 1 + c.rng.int(0, 1))]; return { prompt: `${ex} = ___`, answer: v, numeric: true, hint: 'Parentheses, exponents, × and ÷ left to right, + and − left to right.' }; } },

  // ── Ratios, percents, rates ──
  'ratio.simple': { label: 'Ratios', gen: c => { const a = c.rng.int(2, 9), b = c.rng.int(2, 9); const t1 = T(c), t2 = T(c, 1); return { prompt: `At ${c.world.place} there are ${pl(a, t1)} and ${pl(b, t2)}. Write the ratio of ${t1.many} to ${t2.many} in simplest form.`, answer: `${a / gcd(a, b)}:${b / gcd(a, b)}`, lines: 1 }; } },
  'ratio.equivalent': { label: 'Equivalent ratios', gen: c => { const a = c.rng.int(1, 9), b = c.rng.int(2, 9), k = c.rng.int(2, 8); return { prompt: `${a}:${b} = ___:${b * k}`, answer: a * k, numeric: true, hint: `${b} × ${k} = ${b * k}` }; } },
  'unit.rate': { label: 'Unit rate', gen: c => { const r = c.rng.int(2, by(c, [8, 15, 25, 60])), n = c.rng.int(2, 9); return { prompt: `${N(c)} earns $${r * n} for ${n} hours of helping at ${c.world.place}. How much is that per hour?`, answer: r, numeric: true, lines: 1, steps: [`Unit rate = total ÷ hours.`, `${r * n} ÷ ${n} = ${r}.`, `$${r} per hour.`] }; } },
  'percent.of': { label: 'Percent of a number', gen: c => { const p = c.rng.pick(by(c, [[10, 50], [10, 20, 25, 50], [5, 15, 30, 40, 75], [12, 35, 64, 120]])); const n = c.rng.int(2, 40) * (p % 10 === 0 ? 10 : 20); return { prompt: `${p}% of ${n} = ___`, answer: +((p / 100) * n).toFixed(2), numeric: true, tolerance: 1e-6, hint: `${p}% = ${p}/100.` }; } },
  'percent.change': { label: 'Discounts, tax and tips', gen: c => { const price = c.rng.int(8, 120); const p = c.rng.pick([10, 15, 20, 25, 30]); const k = c.rng.pick(['discount', 'tax', 'tip'] as const); const v = k === 'discount' ? price * (1 - p / 100) : price * (1 + p / 100); return { prompt: `A ${T(c).one} costs $${price}. ${k === 'discount' ? `It is on sale for ${p}% off.` : k === 'tax' ? `Sales tax is ${p}%.` : `You leave a ${p}% tip.`} What is the final price?`, answer: v.toFixed(2), numeric: true, tolerance: 0.01, lines: 2 }; } },
  'proportion.solve': { label: 'Solve proportions', gen: c => { const a = c.rng.int(2, 9), b = c.rng.int(2, 12), k = c.rng.int(2, 9); return { prompt: `Solve for x:  ${a}/${b} = x/${b * k}`, answer: a * k, numeric: true, hint: 'Scale the ratio, or cross-multiply.' }; } },
  'proportion.constant': { label: 'Constant of proportionality', gen: c => { const k = c.rng.int(2, 12); const xs = [1, 2, 3, 4].map(x => x * c.rng.int(1, 2)); return { prompt: `x: ${xs.join(', ')}  →  y: ${xs.map(x => x * k).join(', ')}. What is the constant of proportionality (y = kx)?`, answer: k, numeric: true }; } },
  'scale.drawing': { label: 'Scale drawings', gen: c => { const s = c.rng.int(2, 10), cm = c.rng.int(2, 15); return { prompt: `On a map, 1 cm = ${s} km. Two towns are ${cm} cm apart on the map. What is the real distance?`, answer: s * cm, numeric: true }; } },

  // ── Integers & rational numbers ──
  'integer.compare': { label: 'Compare integers', gen: c => { const a = c.rng.int(-20, 20), b = c.rng.int(-20, 20); return { prompt: `Compare: ${a} ___ ${b}`, kind: 'choice', choices: ['<', '>', '='], answer: a > b ? '>' : a < b ? '<' : '=', visual: c.tier === 'support' ? { type: 'numberline', min: -10, max: 10, step: 1, labels: 'all', marks: [a, b].filter(v => Math.abs(v) <= 10) } : undefined }; } },
  'integer.abs': { label: 'Absolute value', gen: c => { const a = c.rng.int(-50, 50); return { prompt: `|${a}| = ___`, answer: Math.abs(a), numeric: true, hint: 'Distance from zero.' }; } },
  'integer.ops': { label: 'Integer operations', gen: c => { const a = c.rng.int(-15, 15), b = c.rng.int(-12, 12) || 3; const op = c.rng.pick(by(c, [['+'], ['+', '−'], ['+', '−', '×'], ['+', '−', '×', '÷']])); const wrap = (n: number) => (n < 0 ? `(${n})` : String(n)); const ex = op === '÷' ? `${a * b} ÷ ${wrap(b)}` : `${a} ${op} ${wrap(b)}`; const v = op === '+' ? a + b : op === '−' ? a - b : op === '×' ? a * b : a; return { prompt: `${ex} = ___`, answer: v, numeric: true, hint: op === '×' || op === '÷' ? 'Same signs → positive; different signs → negative.' : 'Subtracting a number is adding its opposite.' }; } },
  'rational.ops': { label: 'Rational number operations', gen: c => { const d1 = c.rng.pick([2, 3, 4, 5]), d2 = c.rng.pick([2, 3, 4, 6]); const n1 = c.rng.int(-5, 5) || -1, n2 = c.rng.int(1, 5); const L = lcm(d1, d2); const num = n1 * (L / d1) - n2 * (L / d2); return { prompt: `${n1}/${d1} − ${n2}/${d2} = ___`, answer: num < 0 ? `-${frac(-num, L)}` : frac(num, L) }; } },
  'gcf.lcm': { label: 'GCF and LCM', gen: c => { const a = c.rng.int(4, 36), b = c.rng.int(4, 36); const g = c.rng.chance(0.5); return { prompt: `Find the ${g ? 'greatest common factor' : 'least common multiple'} of ${a} and ${b}.`, answer: g ? gcd(a, b) : lcm(a, b), numeric: true }; } },

  // ── Expressions & equations ──
  'exponent.evaluate': { label: 'Exponents', gen: c => { const b = c.rng.int(2, by(c, [5, 9, 10, 12])), e = c.rng.int(2, by(c, [2, 3, 3, 4])); return { prompt: `${b}^${e} = ___`, answer: b ** e, numeric: true, hint: `${b} multiplied by itself ${e} times.` }; } },
  'expression.evaluate': { label: 'Evaluate expressions', gen: c => { const x = c.rng.int(1, 10), a = c.rng.int(2, 9), b = c.rng.int(1, 20); return { prompt: `Evaluate ${a}x + ${b} when x = ${x}.`, answer: a * x + b, numeric: true, steps: [`Substitute: ${a}(${x}) + ${b}.`, `Multiply: ${a * x} + ${b}.`, `Add: ${a * x + b}.`] }; } },
  'expression.write': { label: 'Write expressions', gen: c => { const n = c.rng.int(2, 12); const forms: Array<[string, string, string[]]> = [[`${n} more than a number x`, `x + ${n}`, [`${n}x`, `x − ${n}`, `${n} − x`]], [`${n} times a number x`, `${n}x`, [`x + ${n}`, `x ÷ ${n}`, `${n} − x`]], [`a number x decreased by ${n}`, `x − ${n}`, [`${n} − x`, `x + ${n}`, `${n}x`]], [`the quotient of a number x and ${n}`, `x ÷ ${n}`, [`${n} ÷ x`, `${n}x`, `x − ${n}`]]]; const [words, ans, wrong] = c.rng.pick(forms); return { prompt: `Which expression means "${words}"?`, kind: 'choice', ...mc(c, ans, wrong) }; } },
  'expression.simplify': { label: 'Combine like terms', gen: c => { const a = c.rng.int(2, 9), b = c.rng.int(1, 9), d = c.rng.int(1, 9), e = c.rng.int(1, 12); const ans = `${a + b}x + ${d + e}`; return { prompt: `Simplify: ${a}x + ${d} + ${b}x + ${e}`, kind: 'choice', ...mc(c, ans, [`${a + b + d + e}x`, `${a + b}x + ${d * e}`, `${a * b}x + ${d + e}`, `${a + d}x + ${b + e}`]) }; } },
  'equation.onestep': { label: 'One-step equations', gen: c => { const x = c.rng.int(by(c, [1, 1, -10, -20]), by(c, [10, 20, 20, 50])), a = c.rng.int(2, 12); const f = c.rng.pick(['add', 'sub', 'mul', 'div'] as const); const ex = f === 'add' ? `x + ${a} = ${x + a}` : f === 'sub' ? `x − ${a} = ${x - a}` : f === 'mul' ? `${a}x = ${a * x}` : `x ÷ ${a} = ${x}`; return { prompt: `Solve: ${ex}`, answer: f === 'div' ? x * a : x, numeric: true, hint: 'Do the inverse operation to both sides.' }; } },
  'equation.twostep': { label: 'Two-step equations', gen: c => { const x = c.rng.int(by(c, [1, -5, -10, -20]), by(c, [10, 12, 20, 30])), a = c.rng.int(2, 9), b = c.rng.int(-15, 20); return { prompt: `Solve: ${a}x ${b < 0 ? '−' : '+'} ${Math.abs(b)} = ${a * x + b}`, answer: x, numeric: true, lines: 2, steps: [`${b < 0 ? 'Add' : 'Subtract'} ${Math.abs(b)} on both sides: ${a}x = ${a * x}.`, `Divide both sides by ${a}: x = ${x}.`, `Check: ${a}(${x}) ${b < 0 ? '−' : '+'} ${Math.abs(b)} = ${a * x + b}. ✓`] }; } },
  'equation.multistep': { label: 'Variables on both sides', gen: c => { const x = c.rng.int(-10, 12), a = c.rng.int(3, 9), b = c.rng.int(1, a - 1), d = c.rng.int(-10, 10); const e = a * x + d - b * x; return { prompt: `Solve: ${a}x ${d < 0 ? '−' : '+'} ${Math.abs(d)} = ${b}x ${e < 0 ? '−' : '+'} ${Math.abs(e)}`, answer: x, numeric: true, lines: 3, hint: 'Collect x-terms on one side, numbers on the other.' }; } },
  'inequality': { label: 'Inequalities', gen: c => { const a = c.rng.int(2, 9), x = c.rng.int(-5, 15), b = c.rng.int(1, 20); const two = diff(c) >= 3; return two ? { prompt: `Solve: ${a}x + ${b} > ${a * x + b}`, answer: `x > ${x}`, lines: 1 } : { prompt: `Which value is a solution of x + ${b} < ${x + b}?`, kind: 'choice', ...mc(c, x - c.rng.int(1, 4), [x, x + 1, x + 3, x + 5]) }; } },
  'sci.notation': { label: 'Scientific notation', gen: c => { const big = c.rng.chance(0.6); const x = big ? c.rng.int(12, 98) * 10 ** c.rng.int(3, 8) : c.rng.int(12, 98) / 10 ** c.rng.int(4, 7); return c.rng.chance(0.5) ? { prompt: `Write ${big ? fmtNum(x) : String(x)} in scientific notation.`, answer: sciN(x), lines: 1 } : { prompt: `Write ${sciN(x)} in standard form.`, answer: big ? fmtNum(x) : String(x), lines: 1 }; } },
  'exponent.rules': { label: 'Exponent rules', gen: c => { const b = c.rng.int(2, 9), m = c.rng.int(2, 8), n = c.rng.int(2, 6); const k = c.rng.pick(['mul', 'div', 'pow'] as const); const [ex, e] = k === 'mul' ? [`${b}^${m} × ${b}^${n}`, m + n] : k === 'div' ? [`${b}^${m + n} ÷ ${b}^${n}`, m] : [`(${b}^${m})^${n}`, m * n]; return { prompt: `Simplify to a single power: ${ex}`, kind: 'choice', ...mc(c, `${b}^${e}`, [`${b}^${m * n + 1}`, `${b}^${Math.abs(m - n) || 1}`, `${b * b}^${e}`, `${b}^${m + n + 1}`]) }; } },
  'roots': { label: 'Square and cube roots', gen: c => { const cube = diff(c) >= 3 && c.rng.chance(0.5); const r = c.rng.int(1, cube ? 6 : 15); return { prompt: cube ? `∛${r ** 3} = ___` : `√${r * r} = ___`, answer: r, numeric: true }; } },
  'irrational': { label: 'Rational or irrational', gen: c => { const items: Array<[string, string]> = [['√2', 'irrational'], ['√49', 'rational'], ['π', 'irrational'], ['0.75', 'rational'], ['1/3', 'rational'], ['√10', 'irrational'], ['0.121212…', 'rational'], ['√81', 'rational']]; const [x, a] = c.rng.pick(items); return { prompt: `Is ${x} rational or irrational?`, kind: 'choice', choices: ['rational', 'irrational'], answer: a }; } },
  'slope': { label: 'Slope', gen: c => { const x1 = c.rng.int(-5, 5), y1 = c.rng.int(-5, 5), dx = c.rng.int(1, 5), m = c.rng.int(-4, 4); const x2 = x1 + dx, y2 = y1 + m * dx; return { prompt: `Find the slope of the line through (${x1}, ${y1}) and (${x2}, ${y2}).`, answer: m, numeric: true, hint: 'slope = rise ÷ run = (y₂ − y₁) ÷ (x₂ − x₁)', steps: [`Rise: ${y2} − (${y1}) = ${y2 - y1}.`, `Run: ${x2} − (${x1}) = ${dx}.`, `Slope: ${y2 - y1} ÷ ${dx} = ${m}.`] }; } },
  'linear.evaluate': { label: 'Linear functions', gen: c => { const m = c.rng.int(-5, 6) || 2, b = c.rng.int(-10, 10), x = c.rng.int(-5, 8); return { prompt: `For y = ${m}x ${b < 0 ? '−' : '+'} ${Math.abs(b)}, find y when x = ${x}.`, answer: m * x + b, numeric: true }; } },
  'linear.identify': { label: 'Slope and y-intercept', gen: c => { const m = c.rng.int(-6, 6) || 3, b = c.rng.int(-9, 9); const askM = c.rng.chance(0.5); return { prompt: `In y = ${m}x ${b < 0 ? '−' : '+'} ${Math.abs(b)}, what is the ${askM ? 'slope' : 'y-intercept'}?`, answer: askM ? m : b, numeric: true }; } },
  'function.table': { label: 'Is it a function?', gen: c => { const xs = c.rng.sample([1, 2, 3, 4, 5, 6], 4); const isF = c.rng.chance(0.5); const pairs = xs.map(x => [x, c.rng.int(0, 12)]); if (!isF) pairs[3] = [pairs[0][0], (pairs[0][1] + 3) % 13]; return { prompt: `Is this relation a function? {${pairs.map(p => `(${p[0]}, ${p[1]})`).join(', ')}}`, kind: 'choice', choices: ['yes', 'no'], answer: isF ? 'yes' : 'no', hint: 'A function gives each input exactly one output.' }; } },
  'system.solve': { label: 'Systems of equations', gen: c => { const x = c.rng.int(-5, 8), y = c.rng.int(-5, 8); const a = c.rng.int(1, 4), b = c.rng.int(1, 4); return { prompt: `Solve the system:  x + y = ${x + y}   and   ${a === 1 ? '' : a}x − ${b === 1 ? '' : b}y = ${a * x - b * y}`, answer: `(${x}, ${y})`, lines: 3, hint: 'Substitute y = (sum) − x into the second equation.' }; } },
  'pythagorean': { label: 'Pythagorean theorem', gen: c => { const [a, b, h] = c.rng.pick([[3, 4, 5], [6, 8, 10], [5, 12, 13], [8, 15, 17], [9, 12, 15], [7, 24, 25], [12, 16, 20]]); const findLeg = diff(c) >= 3 && c.rng.chance(0.5); return findLeg ? { prompt: `A right triangle has hypotenuse ${h} and one leg ${a}. Find the other leg.`, answer: b, numeric: true, visual: { type: 'rightTriangle', a: String(a), b: '?', c: String(h) } } : { prompt: `A right triangle has legs ${a} and ${b}. Find the hypotenuse.`, answer: h, numeric: true, visual: { type: 'rightTriangle', a: String(a), b: String(b), c: '?' }, steps: [`a² + b² = c²`, `${a * a} + ${b * b} = ${h * h}`, `c = √${h * h} = ${h}.`] }; } },
  'circle': { label: 'Circles', gen: c => { const r = c.rng.int(1, 12); const area = c.rng.chance(0.5); return { prompt: `A circle has radius ${r} cm. Find its ${area ? 'area' : 'circumference'}. Use π ≈ 3.14.`, answer: +(area ? 3.14 * r * r : 2 * 3.14 * r).toFixed(2), numeric: true, tolerance: 0.05, hint: area ? 'A = πr²' : 'C = 2πr', visual: { type: 'shape', shape: 'circle' } }; } },
  'volume.solids': { label: 'Cylinders, cones and spheres', gen: c => { const r = c.rng.int(1, 6), h = c.rng.int(2, 12); const k = c.rng.pick(['cylinder', 'cone', 'sphere'] as const); const v = k === 'cylinder' ? 3.14 * r * r * h : k === 'cone' ? (3.14 * r * r * h) / 3 : (4 / 3) * 3.14 * r ** 3; return { prompt: `Find the volume of a ${k} with radius ${r} cm${k === 'sphere' ? '' : ` and height ${h} cm`}. Use π ≈ 3.14. Round to the nearest tenth.`, answer: +v.toFixed(1), numeric: true, tolerance: 0.15, visual: { type: 'shape', shape: k }, hint: k === 'cylinder' ? 'V = πr²h' : k === 'cone' ? 'V = ⅓πr²h' : 'V = ⁴⁄₃πr³' }; } },
  'transform': { label: 'Transformations', gen: c => { const x = c.rng.int(-6, 6), y = c.rng.int(-6, 6); const k = c.rng.pick(['translate', 'reflect-x', 'reflect-y', 'rotate180'] as const); const dx = c.rng.int(-4, 4), dy = c.rng.int(-4, 4); const [nx, ny, words] = k === 'translate' ? [x + dx, y + dy, `translated ${Math.abs(dx)} ${dx < 0 ? 'left' : 'right'} and ${Math.abs(dy)} ${dy < 0 ? 'down' : 'up'}`] : k === 'reflect-x' ? [x, -y, 'reflected over the x-axis'] : k === 'reflect-y' ? [-x, y, 'reflected over the y-axis'] : [-x, -y, 'rotated 180° about the origin']; return { prompt: `Point P(${x}, ${y}) is ${words}. What are the coordinates of P′?`, answer: `(${nx}, ${ny})` }; } },
  'stats.center': { label: 'Mean, median, mode, range', gen: c => { const n = by(c, [5, 5, 7, 8]); const xs = Array.from({ length: n }, () => c.rng.int(1, 20)); const sorted = [...xs].sort((a, b) => a - b); const k = c.rng.pick(['mean', 'median', 'range'] as const); if (k === 'mean') { const s = xs.reduce((a, b) => a + b, 0); const fix = (n - (s % n)) % n; xs[0] += fix; sorted.splice(0, sorted.length, ...[...xs].sort((a, b) => a - b)); } const mean = xs.reduce((a, b) => a + b, 0) / n; const med = n % 2 ? sorted[(n - 1) / 2] : (sorted[n / 2 - 1] + sorted[n / 2]) / 2; return { prompt: `Data: ${xs.join(', ')}. Find the ${k}.`, answer: k === 'mean' ? mean : k === 'median' ? med : sorted[n - 1] - sorted[0], numeric: true, tolerance: 1e-6, lines: 1 }; } },
  'probability': { label: 'Probability', gen: c => { const r = c.rng.int(1, 6), b = c.rng.int(1, 6), g = c.rng.int(0, 5); const tot = r + b + g; return { prompt: `A bag holds ${tot} marbles: ${g ? `${r} red, ${b} blue and ${g} green` : `${r} red and ${b} blue`}. What is the probability of picking a blue marble? Write a fraction.`, answer: frac(b, tot) }; } },
};

/** A worked example for a skill: one generated item at entry difficulty with its steps. */
export function workedExample(skill: string, ctx: GenCtx): WorkedExample | undefined {
  const s = MATH_SKILLS[skill];
  if (!s) return undefined;
  const out = s.gen({ ...ctx, level: 1, tier: 'core' });
  return { prompt: out.prompt.replace(/___/g, '?'), steps: out.steps?.length ? [...out.steps, `Answer: ${out.answer}`] : [out.hint || 'Work it out step by step.', `Answer: ${out.answer}`], visual: out.visual };
}

export const mathSkillIds = () => Object.keys(MATH_SKILLS);
